SELECT posting_date,COUNT(*) AS invoices,SUM(grand_total) AS grand_total,SUM(paid_amount) AS paid_amount,SUM(outstanding_amount) AS outstanding_amount FROM "tabPOS Invoice" WHERE docstatus=1 AND (%(company)s='' OR company=%(company)s) AND (%(from_date)s='' OR posting_date>=%(from_date)s) AND (%(to_date)s='' OR posting_date<=%(to_date)s) GROUP BY posting_date ORDER BY posting_date DESC
